#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define W for (i=0;i<tmp;i++)
#define OFF1 5
#define OFF2 2
#define INTOFF 9
#define LITSIZE 4

int i;
int radix = 255;
int fraction = 0;
long range = 1;
int cc[1000000];
unsigned char output_buf[10000];
int output_pos = 0;

void put_byte(unsigned char c) {
  if (output_pos < 10000) {
    output_buf[output_pos++] = c;
  }
}

void put_bit(int ctx, int bit) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
    put_byte(fraction / radix + 1);
    fraction %= radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * -~*counts / (*counts + counts[1] + 2);

  if (bit) {
    fraction += split;
  }
  range = bit ? range - split : split;
  counts[bit]++;
}

void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  int result_ans = val + subtract_it;

  ctx *= 99;
  int tmp = nbits;
  while (!(result_ans & (1 << tmp))) {
    put_bit(++tmp + ctx, 0);
  }
  put_bit(tmp + ctx, 1);
  tmp--;

  W {
    put_bit(ctx, (result_ans >> tmp) & 1);
  }
}

int main() {
  char buf[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF) {
    buf[len++] = c;
  }

  // Write the count of symbols
  put_integer(len, 9, 0);

  // Simple encoding: just write each character as a literal
  for (int i = 0; i < len; i++) {
    put_bit(1, 0);  // literal flag
    put_integer((unsigned char)buf[i], LITSIZE, 9);
  }

  // Flush remaining bits
  if (fraction > 0 || range < radix) {
    put_byte((fraction + 1) * radix / range);
  }

  fwrite(output_buf, 1, output_pos, stdout);

  return 0;
}
