#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
long fraction = 0;
long range = 1;
int tmp;
int cc[1000000];
unsigned char output_buf[100000];
int output_pos = 0;

void put_bit(int ctx, int bit) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
    unsigned char byte_to_write = (fraction / radix) + 1;
    output_buf[output_pos++] = byte_to_write;
    fraction = fraction % radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * (1 + counts[0]) / (counts[0] + counts[1] + 2);

  if (bit) {
    fraction += split;
  }
  range = bit ? (range - split) : split;
  counts[bit]++;
}

void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  int result_ans = val + subtract_it;
  ctx *= 99;

  tmp = nbits;

  /* Find the highest set bit position in result_ans */
  int highest_bit = -1;
  for (int b = 30; b >= 0; b--) {
    if ((result_ans >> b) & 1) {
      highest_bit = b;
      break;
    }
  }

  /* We need to emit unary bits to indicate how many data bits follow.
     The decompressor loop does: while (!get_bit(++tmp+ctx))
     Each iteration increments tmp, and we emit 0.
     When we emit 1, the loop exits.
     Then tmp-- is called.

     If we emit k zeros then a 1:
     - Loop does: ++tmp (k+1 times total, k for the 0s, 1 for exiting)
     - After loop: tmp = nbits + k + 1
     - After tmp--: tmp = nbits + k
     - Read nbits+k bits
     - result_ans becomes: (1 << (nbits+k)) | (read_bits) - subtract_it

     We need: (1 << (nbits+k)) + read_bits - subtract_it = val
     So: read_bits = val + subtract_it - (1 << (nbits+k))

     For this to work, we need highest_bit <= nbits+k
     So: k >= highest_bit - nbits
     Let k = max(0, highest_bit - nbits)
  */

  int k = (highest_bit > nbits) ? (highest_bit - nbits) : 0;

  /* Emit k zero bits at contexts nbits+1, nbits+2, ..., nbits+k */
  for (int j = 0; j < k; j++) {
    put_bit(++tmp + ctx, 0);
  }

  /* Emit the 1 bit at context nbits+k+1 */
  put_bit(++tmp + ctx, 1);

  /* Now tmp = nbits+k+1, after tmp-- it becomes nbits+k */
  tmp--;

  /* Emit nbits+k bits from result_ans */
  W {
    put_bit(ctx, (result_ans >> tmp) & 1);
  }
}

