  char buf[20000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF) {
    buf[len++] = c;
  }

  put_integer(len, 9, 0);

  for (int i = 0; i < len; i++) {
    put_bit(1, 0);
    unsigned char ch = (unsigned char)buf[i];
    put_bit(8, 0);
    put_integer(ch, 4, 9);
  }

  while (range < radix) {
    range *= radix;
    fraction *= radix;
    unsigned char byte_to_write = (fraction / radix) + 1;
    output_buf[output_pos++] = byte_to_write;
    fraction = fraction % radix;
  }

