#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
long fraction = 0;
long range = 1;
int tmp;
int cc[1000000];
unsigned char output_buf[100000];
int output_pos = 0;

void put_bit(int ctx, int bit) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
    unsigned char byte_to_write = (fraction / radix) + 1;
    output_buf[output_pos++] = byte_to_write;
    fraction = fraction % radix;
  }

  int *counts = cc + ctx * 2;
  int split = range * (1 + counts[0]) / (counts[0] + counts[1] + 2);

  if (bit) {
    fraction += split;
  }
  range = bit ? (range - split) : split;
  counts[bit]++;
}

void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  int result_ans = val + subtract_it;
  ctx *= 99;

  tmp = nbits;
  int highest_bit = -1;
  for (int b = 30; b >= 0; b--) {
    if ((result_ans >> b) & 1) {
      highest_bit = b;
      break;
    }
  }

  int k = (highest_bit > nbits) ? (highest_bit - nbits) : 0;

  /* Emit k zeros at contexts nbits+1, ..., nbits+k */
  for (int j = 0; j < k; j++) {
    put_bit(++tmp + ctx, 0);
  }

  /* Emit 1 at context nbits+k+1 */
  put_bit(++tmp + ctx, 1);

  /* Now emit nbits+k bits from result_ans */
  tmp--;
  W {
    put_bit(ctx, (result_ans >> tmp) & 1);
  }
}

int main() {
  char buf[20000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF) {
    buf[len++] = c;
  }

  put_integer(len, 9, 0);

  for (int i = 0; i < len; i++) {
    put_bit(1, 0);
    unsigned char ch = (unsigned char)buf[i];
    put_bit(8, 0);
    put_integer(ch, 4, 9);
  }

  while (range < radix) {
    range *= radix;
    fraction *= radix;
    unsigned char byte_to_write = (fraction / radix) + 1;
    output_buf[output_pos++] = byte_to_write;
    fraction = fraction % radix;
  }

  fwrite(output_buf, 1, output_pos, stdout);

  return 0;
}
